function obliczSume(a, b) {
  debugger;
  return a + b;
}

obliczSume(2, 3);

// F5        - uruchom / kontynuuj do nastepnego breakpointa
// F9        - przelacz breakpoint w aktualnej linii
// F10       - step over (nastepna linia, bez wchodzenia do funkcji)
// F11       - step into (wejdz do wnetrza wywolywanej funkcji)
// Shift+F11 - step out (wyjdz z aktualnej funkcji)

const uzytkownicy = [
  { id: 1, imie: "Ola" },
  { id: 2, imie: "Piotr" },
];
console.table(uzytkownicy);

console.time("petla");
let suma = 0;
for (let i = 1; i <= 1000000; i++) {
  suma += i;
}
console.timeEnd("petla"); // np. "petla: 4.1ms"
console.log(suma);

function podzielKwote(kwota, liczbaOsob) {
  // breakpoint TUTAJ (poczatek funkcji) pozwolilby od razu sprawdzic
  // aktualne wartosci 'kwota' i 'liczbaOsob' - dla liczbaOsob = 0,
  // dzielenie kwota / 0 w JavaScript daje Infinity (nie blad!), co
  // mozna od razu zauwazyc podgladajac wynik krok po kroku (F10).
  return kwota / liczbaOsob;
}

console.log(podzielKwote(100, 0)); // Infinity

// step over (F10) wykonuje CALE wywolanie funkcji jako JEDEN krok -
// jesli aktualna linia wywoluje inna funkcje, debugger przechodzi
// PROSTO do linii NASTEPNEJ po tym wywolaniu, bez pokazywania, co
// dzieje sie w srodku.
// step into (F11) 'wchodzi' do wnetrza wywolywanej funkcji, pozwalajac
// sledzic jej wykonanie linia po linii - uzywane, gdy podejrzewasz
// problem WEWNATRZ tej konkretnej, wywolywanej funkcji.

// Kazdy dodany console.log wymaga edycji kodu (i pozniejszego jego
// usuniecia) oraz pokazuje TYLKO to, co jawnie wypisano. Breakpoint
// zatrzymuje wykonanie BEZ zadnej zmiany kodu i pozwala od razu
// podgladnac WSZYSTKIE zmienne dostepne w danym miejscu (panel
// 'Variables'/'Scope'), a nastepnie przejsc krok po kroku dalej,
// obserwujac jak zmienia sie stan po kazdej linii - przy zlozonej,
